WITH cleaned AS (SELECT *, INITCAP(TRIM(merchant)) AS merchant_title, CASE WHEN merchant = 'Shell' THEN 1 ELSE 0 END AS is_shell, COALESCE(merchant, 'DIRECT') AS resolved_merchant FROM transactions WHERE txn_time < '2024-08-30' AND txn_time > TO_DATE('2023-10-06')), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_session FROM cleaned), sessionized AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, resolved_merchant, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN amount >= 4500 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, CASE WHEN burst_id >= 6 THEN 'PREMIUM' ELSE 'STANDARD' END AS burst_id_tier, SUM(burst_id) AS total_burst_id, COUNT(*) AS num_rows, COUNT(DISTINCT txn_type) AS distinct_txn_types FROM sessionized GROUP BY amount_tier, burst_id_tier;
